mapper.select:
SELECT u.*
FROM users u
WHERE u.id = #{id}

SELECT u.* FROM users u LEFT JOIN user_roles ur ON u.id = ur.user_id LEFT JOIN roles r ON ur.role_id = r.id WHERE u.status != 9
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
AND u.status = #{status}
AND u.role = #{role}
ORDER BY u.created_at DESC
